// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_integSrchNo", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("integSrchNo")))); } },
        { childId: "ipt_searchRelLawNm", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("searchRelLawNm")))); } },
        { childId: "ipt_searchRelLawNm2", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("searchRelLawNm")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.util.getComponent('slc_chargInstId').setValue('' + dma_integSrchDetail.get("chrg_inst_id") + '');
        $c.util.getComponent('slc_ldMktTpCd').setValue('' + dma_integSrchDetail.get("ld_mkt_tp_cd") + '');
        $c.util.getComponent('slc_submitDeadlineId').setValue('' + dma_integSrchDetail.get("submit_deadline_id") + '');
        $c.util.getComponent('slc_disclsTpId').setValue('' + dma_integSrchDetail.get("discls_tp_id") + '');
        const formCd = $c.util.getComponent('ipt_formCd').getValue();
        if (formCd.length > 0) {
            setInputDisable($('#integSrchNm'));
            setBtnDisable($('#formSearchSpan'));
        } else {
            setBtnDisable($('#formDelSpan'));
        }
        setBtnDisable($('#duplChkSpan'));
        scwin.fn_searchKeywrdListDtl();
        const integDiv = $('input:radio[name="integDiv"]:checked').val();
        if (integDiv === '2') {
            setInputEnable($('#integSrchNm'));
            setBtnDisable($('#formSearchSpan'));
            $c.util.getComponent('ipt_integSrchNmChck').setValue("N");
        }
        if (dma_hiddenStore.get("integSrchNm").length > 0) {
            $c.util.getComponent('ipt_integSrchNmChck').setValue("Y");
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf70010.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.editor = undefined; try { scwin.editor = /* sdd-asis-lifecycle:begin editor — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Dext5editor("dext5editor1")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf70010' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf70010.onpageload' });
    }
};


