    setBtnEnable($("#formDelSpan"));
    setInputDisable($('#integSrchNm'));
    setBtnDisable($("#duplChkSpan"));
    $('input:radio[name="integDiv"][value="1"]').prop('checked', true);
    /* sdd-asis-lifecycle:end */
};


